<script>
  // Deterministic catalog. Note: the cheapest item OVERALL is in Water
  // ($9.95); the cheapest CAMPING item is the Titanium Tent Stakes ($11.50).
  const PRODUCTS = [
    { name: "Alpine Tent 2P",        cat: "Camping",  price: 189.00, blurb: "Freestanding two-person shelter, 1.9 kg." },
    { name: "Down Sleeping Bag",     cat: "Camping",  price: 129.50, blurb: "800-fill, comfort to -7°C." },
    { name: "Titanium Tent Stakes",  cat: "Camping",  price: 11.50,  blurb: "Set of 6, 8 g each." },
    { name: "Camp Stove",            cat: "Camping",  price: 44.99,  blurb: "Canister stove, 3.5 min boil." },
    { name: "Headlamp 400lm",        cat: "Camping",  price: 24.95,  blurb: "USB-C, red mode, IPX6." },
    { name: "Dynamic Rope 60m",      cat: "Climbing", price: 159.00, blurb: "9.8 mm, dry treated." },
    { name: "Climbing Harness",      cat: "Climbing", price: 64.50,  blurb: "Adjustable legs, 4 gear loops." },
    { name: "Chalk Bag",             cat: "Climbing", price: 14.25,  blurb: "Fleece lined, belt included." },
    { name: "Carabiner Set",         cat: "Climbing", price: 29.99,  blurb: "5 wiregate, 24 kN." },
    { name: "Belay Device",          cat: "Climbing", price: 22.40,  blurb: "Tube style, guide mode." },
    { name: "Dry Bag 20L",           cat: "Water",    price: 9.95,   blurb: "Roll-top, welded seams." },
    { name: "Packraft",              cat: "Water",    price: 349.00, blurb: "2.3 kg, inflates in 4 min." },
    { name: "Water Filter",          cat: "Water",    price: 34.75,  blurb: "Hollow fiber, 2 L/min." },
    { name: "Kayak Paddle",          cat: "Water",    price: 89.00,  blurb: "Fiberglass, 2-piece." },
    { name: "Neoprene Gloves",       cat: "Water",    price: 17.60,  blurb: "3 mm, pre-curved." },
  ];

  // --- filler catalogue -----------------------------------------------------
  // Deterministic, and deliberately in categories that do NOT contain the
  // answers: the cheapest Camping item and the priciest Water item must stay
  // the ones the ladder checks for. This exists to make the page BIG — a real
  // catalogue is thousands of nodes, and that is what makes context strategy
  // matter.
  const FILLER_CATS = ["Apparel", "Navigation", "Cooking", "Footwear", "Lighting", "Packs"];
  const FILLER_WORDS = ["Trail", "Summit", "Ridge", "Alpine", "Basin", "Cirque", "Tundra", "Fjord"];
  const FILLER_NOUNS = ["Jacket", "Compass", "Pot", "Boot", "Lantern", "Daypack", "Glove", "Map"];
  for (let i = 0; i < 240; i++) {
    const cat = FILLER_CATS[i % FILLER_CATS.length];
    const w = FILLER_WORDS[(i * 3) % FILLER_WORDS.length];
    const n = FILLER_NOUNS[(i * 5) % FILLER_NOUNS.length];
    PRODUCTS.push({
      name: w + " " + n + " " + (100 + i),
      cat: cat,
      // 19.00-238.00: never cheaper than the Titanium Tent Stakes (11.50) and
      // never dearer than the Packraft (349.00), so the answers are stable.
      price: 19 + ((i * 7) % 220),
      blurb: "Model " + (100 + i) + ". Field-tested " + n.toLowerCase() + " for " + cat.toLowerCase() + " use, three-season rated.",
    });
  }

  const cart = [];
  const fmt = (n) => "$" + n.toFixed(2);

  function renderCatalog() {
    const cats = [...new Set(PRODUCTS.map((p) => p.cat))];
    const root = document.getElementById("catalog");
    for (const cat of cats) {
      const h = document.createElement("h2");
      h.textContent = cat;
      root.appendChild(h);
      const grid = document.createElement("div");
      grid.className = "grid";
      for (const p of PRODUCTS.filter((x) => x.cat === cat)) {
        const card = document.createElement("div");
        card.className = "product";
        card.innerHTML =
          "<h3>" + p.name + "</h3><p>" + p.blurb + "</p>" +
          '<div class="row"><span class="price">' + fmt(p.price) + "</span></div>";
        const btn = document.createElement("button");
        btn.textContent = "Add to cart";
        btn.setAttribute("aria-label", "Add " + p.name + " to cart");
        btn.addEventListener("click", () => addToCart(p));
        card.querySelector(".row").appendChild(btn);
        grid.appendChild(card);
      }
      root.appendChild(grid);
    }
  }

  function renderCart() {
    const ul = document.getElementById("cart-items");
    ul.innerHTML = "";
    if (cart.length === 0) {
      ul.innerHTML = '<li id="cart-empty">Cart is empty.</li>';
    } else {
      for (const p of cart) {
        const li = document.createElement("li");
        li.textContent = p.name + " — " + fmt(p.price);
        ul.appendChild(li);
      }
    }
    const total = cart.reduce((a, p) => a + p.price, 0);
    document.getElementById("cart-total").textContent = "Total: " + fmt(total);
    document.getElementById("cart-count").textContent =
      "Cart (" + cart.length + " item" + (cart.length === 1 ? "" : "s") + ")";
  }

  function addToCart(p) { cart.push(p); renderCart(); }
  document.getElementById("clear-cart").addEventListener("click", () => { cart.length = 0; renderCart(); });
  renderCatalog();
</script>


